import { neon } from "@neondatabase/serverless";

const databaseUrl = process.env.DATABASE_URL;
if (!databaseUrl) throw new Error("DATABASE_URL est absente.");

const sql = neon(databaseUrl);

await sql.query(
  "ALTER TABLE vtc_drivers ADD COLUMN IF NOT EXISTS driver_number bigint GENERATED BY DEFAULT AS IDENTITY",
);
await sql.query(
  "CREATE UNIQUE INDEX IF NOT EXISTS vtc_drivers_driver_number_idx ON vtc_drivers(driver_number)",
);
await sql.query("ALTER TABLE vtc_drivers ADD COLUMN IF NOT EXISTS first_name text");
await sql.query("ALTER TABLE vtc_drivers ADD COLUMN IF NOT EXISTS bio text");
await sql.query(
  "ALTER TABLE vtc_drivers ADD COLUMN IF NOT EXISTS other_activities text[] NOT NULL DEFAULT '{}'",
);
await sql.query(
  "ALTER TABLE vtc_drivers ADD COLUMN IF NOT EXISTS languages text[] NOT NULL DEFAULT '{}'",
);
await sql.query(
  "ALTER TABLE vtc_drivers ADD COLUMN IF NOT EXISTS interests text[] NOT NULL DEFAULT '{}'",
);
await sql.query("ALTER TABLE vtc_drivers ADD COLUMN IF NOT EXISTS phone text");
await sql.query("ALTER TABLE vtc_drivers ADD COLUMN IF NOT EXISTS email text");
await sql.query("ALTER TABLE vtc_drivers ADD COLUMN IF NOT EXISTS website text");
await sql.query("ALTER TABLE vtc_drivers ADD COLUMN IF NOT EXISTS vcard text");

await sql.query(
  `UPDATE vtc_drivers
   SET first_name = COALESCE(first_name, 'Alexandre'),
       bio = COALESCE(bio, 'Chauffeur professionnel attentif, je veille à rendre chaque trajet agréable et serein.'),
       other_activities = CASE WHEN cardinality(other_activities) = 0
         THEN ARRAY['Entrepreneur', 'Ambassadeur local'] ELSE other_activities END,
       languages = CASE WHEN cardinality(languages) = 0
         THEN ARRAY['Français', 'Anglais', 'Allemand'] ELSE languages END,
       interests = CASE WHEN cardinality(interests) = 0
         THEN ARRAY['Voyages', 'Gastronomie', 'Patrimoine régional'] ELSE interests END,
       phone = COALESCE(phone, '+33 6 22 80 55 36'),
       email = COALESCE(email, 'contact@welcome-coworking.com'),
       website = COALESCE(website, 'https://www.welcome-coworking.com'),
       vcard = COALESCE(vcard, E'BEGIN:VCARD\\r\\nVERSION:3.0\\r\\nFN:Votre chauffeur Welcome\\r\\nN:;Alexandre;;;\\r\\nTEL;TYPE=CELL:+33 6 22 80 55 36\\r\\nEMAIL;TYPE=INTERNET:contact@welcome-coworking.com\\r\\nURL:https://www.welcome-coworking.com\\r\\nNOTE:Chauffeur professionnel attentif, je veille à rendre chaque trajet agréable et serein.\\r\\nEND:VCARD')
   WHERE slug = 'demo'`,
);

const columns = await sql.query(
  `SELECT column_name, data_type, is_nullable, is_identity, identity_generation
   FROM information_schema.columns
   WHERE table_schema = 'public'
     AND table_name = 'vtc_drivers'
     AND column_name IN (
       'driver_number', 'first_name', 'bio', 'other_activities', 'languages',
       'interests', 'phone', 'email', 'website', 'vcard'
     )
   ORDER BY ordinal_position`,
);
const drivers = await sql.query(
  `SELECT driver_number, slug, display_name, first_name, other_activities, languages,
          interests, phone, email, website, vcard
   FROM vtc_drivers
   ORDER BY driver_number`,
);

console.log(JSON.stringify({ columns, drivers }, null, 2));
